<?php

if (PHP_SAPI !== 'cli') {
    http_response_code(404);
    exit;
}

// Evaluate the simple equality predicates generated by these table models.
function matchesClientSwitchWhere(string $where, array $row): bool {
    $where = trim(str_replace('`', '', $where));
    if ($where === '') return true;
    foreach ([' OR ', ' AND '] as $operator) {
        $depth = 0;
        for ($i = 0; $i < strlen($where); $i++) {
            if ($where[$i] === '(') $depth++;
            if ($where[$i] === ')') $depth--;
            if ($depth === 0 && substr($where, $i, strlen($operator)) === $operator) {
                $left = matchesClientSwitchWhere(substr($where, 0, $i), $row);
                $right = matchesClientSwitchWhere(substr($where, $i + strlen($operator)), $row);
                return $operator === ' OR ' ? $left || $right : $left && $right;
            }
        }
    }
    if ($where[0] === '(' && substr($where, -1) === ')') return matchesClientSwitchWhere(substr($where, 1, -1), $row);
    check((bool)preg_match('/^([a-z]+)\s*=\s*(-?\d+)$/', $where, $match), 'Unsupported fixture predicate: ' . $where);
    return (int)$row[$match[1]] === (int)$match[2];
}

class ClientSwitchFixtureAdapter extends Zend_Db_Adapter_Pdo_Mysql {
    public array $users = [];
    public array $clients = [];
    public array $permissions = [];
    protected function _connect() {}
    public function describeTable($tableName, $schemaName = null) {
        $metadata = [];
        foreach (['id', 'userid', 'clientid', 'admin', 'activated', 'deleted', 'parentid', 'company'] as $column) {
            $metadata[$column] = ['COLUMN_NAME'=>$column, 'DATA_TYPE'=>'int', 'PRIMARY'=>$column === 'id', 'PRIMARY_POSITION'=>1, 'IDENTITY'=>false];
        }
        return $metadata;
    }
    public function query($sql, $bind = []) {
        check($sql instanceof Zend_Db_Table_Select && !$bind, 'Unexpected query or database mutation');
        $sql->assemble();
        $from = $sql->getPart(Zend_Db_Select::FROM);
        $table = reset($from)['tableName'];
        check(in_array($table, ['user', 'client', 'permission'], true), 'Unexpected fixture table');
        $rows = ['user' => $this->users, 'client' => $this->clients, 'permission' => $this->permissions][$table];
        $where = implode(' ', $sql->getPart(Zend_Db_Select::WHERE));
        $rows = array_values(array_filter($rows, static fn($row) => matchesClientSwitchWhere($where, $row)));
        if ($limit = $sql->getPart(Zend_Db_Select::LIMIT_COUNT)) $rows = array_slice($rows, 0, $limit);
        return new class($rows) {
            public function __construct(private array $rows) {}
            public function fetchAll($mode) { return $this->rows; }
        };
    }
}

